WITH orders_agg AS (SELECT DATE_TRUNC('MONTH', orders.ordered_at) AS ordered_at_month, stores.store_name AS store_name, COUNT(DISTINCT orders.order_id) AS orders FROM comparison_orders AS orders JOIN comparison_stores AS stores ON orders.store_id = stores.store_id GROUP BY DATE_TRUNC('MONTH', orders.ordered_at), stores.store_name), order_items_agg AS (SELECT DATE_TRUNC('MONTH', orders.ordered_at) AS ordered_at_month, stores.store_name AS store_name, SUM(order_items.item_revenue_cents / 100.0) AS item_revenue_usd FROM comparison_order_items AS order_items JOIN comparison_orders AS orders ON orders.order_id = order_items.order_id JOIN comparison_stores AS stores ON orders.store_id = stores.store_id GROUP BY DATE_TRUNC('MONTH', orders.ordered_at), stores.store_name) SELECT COALESCE(orders_agg.ordered_at_month, order_items_agg.ordered_at_month) AS ordered_at_month, COALESCE(orders_agg.store_name, order_items_agg.store_name) AS store_name, orders_agg.orders, order_items_agg.item_revenue_usd FROM orders_agg JOIN order_items_agg ON orders_agg.ordered_at_month = order_items_agg.ordered_at_month AND orders_agg.store_name = order_items_agg.store_name ORDER BY 1, 2 LIMIT 5000